const input = $json.body || $json;
const first = (...values) => {
  for (const value of values) {
    if (value !== undefined && value !== null && String(value).trim()) return String(value).trim();
  }
  return '';
};

const originalMessage = first(
  input.message,
  input.inquiry,
  input.question,
  input.details,
  input.notes,
  input.description,
  input.body,
  input.text
);

const normalized = {
  receivedAt: new Date().toISOString(),
  source: first(input.source, input.form_name, input.formName, input.channel, 'Webhook'),
  leadName: first(input.name, input.full_name, input.fullName, input.leadName, input.contact_name),
  email: first(input.email, input.contact_email, input.Email),
  phone: first(input.phone, input.telephone, input.mobile),
  company: first(input.company, input.business, input.organization),
  originalMessage,
  rawPayload: JSON.stringify(input)
};

if (!normalized.originalMessage) {
  normalized.originalMessage = normalized.rawPayload;
}

return [{ json: normalized }];

const response = $input.first().json;
const original = $items('Normalize Lead Input')[0].json;
const text = response.choices?.[0]?.message?.content || response.body?.choices?.[0]?.message?.content || '';
const match = String(text).match(/\{[\s\S]*\}/);
if (!match) {
  throw new Error('OpenAI response did not contain JSON: ' + text);
}

let analysis;
try {
  analysis = JSON.parse(match[0]);
} catch (error) {
  throw new Error('Could not parse OpenAI JSON: ' + error.message + ' Raw: ' + text);
}

const clampScore = (value) => {
  const number = Number(value);
  if (Number.isNaN(number)) return 0;
  return Math.max(1, Math.min(10, Math.round(number)));
};

const leadType = analysis.leadType || 'Warm';
const statusByType = {
  Hot: 'New - Hot',
  Warm: 'New - Warm',
  Cold: 'New - Cold',
  Spam: 'Archived - Spam',
  'Not a Lead': 'Archived - Not a Lead'
};

return [{
  json: {
    Date: new Date(original.receivedAt).toISOString().slice(0, 10),
    Source: original.source || '',
    'Lead Name': original.leadName || '',
    Email: original.email || '',
    Phone: original.phone || '',
    Company: original.company || '',
    'Original Message': original.originalMessage || '',
    'Need Summary': analysis.needSummary || '',
    'Lead Type': leadType,
    Urgency: analysis.urgency || '',
    'Budget Signal': analysis.budgetSignal || '',
    'Problem Category': analysis.problemCategory || '',
    'AI Qualification': analysis.aiQualification || '',
    'Suggested Reply': analysis.suggestedReply || '',
    'Next Action': analysis.nextAction || '',
    'Follow-up Date': analysis.followUpDate || '',
    Status: statusByType[leadType] || 'New - Review',
    'Confidence Score': clampScore(analysis.confidenceScore),
    Notes: analysis.notes || ''
  }
}];
